    const record = recordTriage(inboxUlid, "defer", "not ready yet");

    kspec(`triage act @${record._ulid.slice(0, 8)}`, tempDir);

    // Verify record transitioned to acted_on
    const records = kspecJson<Array<{ _ulid: string; status: string }>>(
      "triage list",
      tempDir,
    );
