import * as readline from "node:readline";
import { ulid } from "ulid";
import type { Command } from "commander";
import { markMutating } from "../command-annotations.js";
import {
  createObservation,
  createTask,
  deleteInboxItem,
  findInboxItemByRef,
  getAuthor,
  initContext,
  type LoadedInboxItem,
  type LoadedTriageRecord,
  loadAllItems,
  loadAllTasks,
  loadInboxItems,
  loadTriageRecords,
  ReferenceIndex,
  saveObservation,
  saveTask,
  saveTriageRecord,
  findTriageRecordByRef,
} from "../../parser/index.js";
import { commitIfShadow } from "../../parser/shadow.js";
import type { TriageAction, TriageRecord } from "../../schema/index.js";
import { errors } from "../../strings/index.js";
import { formatRelativeTime as formatRelativeTimeUtil } from "../../utils/time.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, info, output, success } from "../output.js";

/**
 * Format relative time for display
 */
function formatRelativeTime(dateStr: string): string {
  return formatRelativeTimeUtil(new Date(dateStr));
}

/**
 * Resolve triage record ref with error handling
 */
function resolveTriageRef(
  ref: string,
  records: LoadedTriageRecord[],
): LoadedTriageRecord {
  const record = findTriageRecordByRef(records, ref);
  if (!record) {
    error(`Triage record not found: ${ref}`);
    process.exit(EXIT_CODES.NOT_FOUND);
  }
  return record;
}

/**
 * Simple prompt for user input
 */
async function prompt(question: string): Promise<string> {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  return new Promise((resolve) => {
    rl.question(question, (answer) => {
      rl.close();
      resolve(answer.trim());
    });
  });
}

/**
 * Truncate text for display
 */
function truncateText(text: string, maxLen: number = 60): string {
  const firstLine = text.split("\n")[0].trim();
  if (firstLine.length <= maxLen) return firstLine;
  return `${firstLine.slice(0, maxLen - 3)}...`;
}

/**
 * Execute a triage action
 * AC: @triage-cli-commands ac-4, ac-5, ac-6, ac-7, ac-8
 */
async function executeTriageAction(
  record: LoadedTriageRecord,
  ctx: Awaited<ReturnType<typeof initContext>>,
  dryRun: boolean = false,
): Promise<{ resultRef?: string }> {
  const action = record.override_reasoning ? (record.action as TriageAction) : record.action;
  if (!action) {
    error("Record has no action to execute");
    process.exit(EXIT_CODES.VALIDATION_FAILED);
  }

  switch (action) {
    case "promote": {
      // AC: @triage-cli-commands ac-4
      if (dryRun) {
        info(`Would create task from inbox item snapshot: "${truncateText(record.item_snapshot)}"`);
        return {};
      }
      const task = createTask({
        title: record.item_snapshot.split("\n")[0].slice(0, 100),
        type: "task",
        priority: 3,
        spec_ref: null,
        tags: [],
        description: record.item_snapshot,
      });
      await saveTask(ctx, task);
      const tasks = await loadAllTasks(ctx);
      const items = await loadAllItems(ctx);
      const index = new ReferenceIndex(tasks, items);
      const taskRef = `@${index.shortUlid(task._ulid)}`;
      info(`Created task: ${taskRef} - ${task.title}`);
      return { resultRef: taskRef };
    }

    case "delete": {
      // AC: @triage-cli-commands ac-5
      if (dryRun) {
        info(`Would delete inbox item: ${record.inbox_ref.slice(0, 8)}`);
        return {};
      }
      const inboxItems = await loadInboxItems(ctx);
      const inboxItem = findInboxItemByRef(inboxItems, record.inbox_ref);
      if (inboxItem) {
        await deleteInboxItem(ctx, inboxItem._ulid);
        info(`Deleted inbox item: ${record.inbox_ref.slice(0, 8)}`);
      }
      return {};
    }

    case "defer": {
      // AC: @triage-cli-commands ac-6
      if (dryRun) {
        info(`Would defer: no side effects beyond recording the deferral`);
        return {};
      }
      return {};
    }

    case "spec-gap": {
      // AC: @triage-cli-commands ac-7
      if (dryRun) {
        info(`Would create spec-gap observation from: "${truncateText(record.item_snapshot)}"`);
        return {};
      }
      const content = `${record.item_snapshot}\n\nReasoning: ${record.reasoning || ""}`;
      const observation = createObservation("idea", content, {
        configAuthor: ctx.config?.identity?.author,
      });
      await saveObservation(ctx, observation);
      const obsRef = `@${observation._ulid.slice(0, 8)}`;
      info(`Created spec-gap observation: ${obsRef}`);
      return { resultRef: obsRef };
    }

    case "duplicate": {
      // AC: @triage-cli-commands ac-8
      if (dryRun) {
        info(`Would delete duplicate inbox item: ${record.inbox_ref.slice(0, 8)}`);
        return {};
      }
      const dupItems = await loadInboxItems(ctx);
      const dupItem = findInboxItemByRef(dupItems, record.inbox_ref);
      if (dupItem) {
        await deleteInboxItem(ctx, dupItem._ulid);
        info(`Deleted duplicate inbox item: ${record.inbox_ref.slice(0, 8)}`);
      }
      return {};
    }
  }
}

/**
 * Format a triage record for context export
 * AC: @triage-cli-commands ac-13
 */
function formatTriageContext(record: TriageRecord): string {
  const lines: string[] = [];
  lines.push(`### ${record._ulid.slice(0, 8)} — ${truncateText(record.item_snapshot, 80)}`);
  lines.push("");
  lines.push(`**Item:** ${record.item_snapshot}`);
  lines.push(`**Status:** ${record.status}`);
  if (record.action) lines.push(`**Action:** ${record.action}`);
  if (record.reasoning) lines.push(`**Reasoning:** ${record.reasoning}`);
  if (record.decided_by) lines.push(`**Decided by:** ${record.decided_by}`);
  if (record.evidence_refs.length > 0) {
    lines.push(`**Evidence:** ${record.evidence_refs.join(", ")}`);
  }
  if (record.override_reasoning) {
    lines.push(`**Override:** ${record.override_reasoning} (by ${record.override_by || "unknown"})`);
  }
  if (record.acted_at) {
    lines.push(`**Acted at:** ${record.acted_at}`);
    if (record.result_ref) lines.push(`**Result:** ${record.result_ref}`);
  }
  lines.push("");
  return lines.join("\n");
}

/**
 * Register the 'triage' command group
 * AC: @triage-cli-commands ac-1 through ac-17
 */
export function registerTriageCommands(program: Command): void {
  const triage = program
    .command("triage")
    .description("Record, review, and act on triage decisions");

  // kspec triage record <inbox-ref>
  // AC: @triage-cli-commands ac-1, ac-11
  markMutating(triage.command("record <inbox-ref>"))
    .description("Record a triage decision for an inbox item")
    .requiredOption("--action <action>", "Triage action (promote, delete, defer, spec-gap, duplicate)")
    .requiredOption("--reasoning <text>", "Reasoning for the decision")
    .option("--decided-by <author>", "Who made the decision")
    .option("--evidence <refs...>", "Evidence references")
    .option("--dry-run", "Show what would happen without making changes")
    .addHelpText(
      "after",
      `
Examples:
  $ kspec triage record @ref --action promote --reasoning "clear feature request"
  $ kspec triage record @ref --action defer --reasoning "needs more discussion"`,
    )
    .action(async (inboxRef: string, options) => {
      try {
        const ctx = await initContext();

        // Validate action
        const validActions = ["promote", "delete", "defer", "spec-gap", "duplicate"];
        if (!validActions.includes(options.action)) {
          error(`Invalid action: ${options.action}. Must be one of: ${validActions.join(", ")}`);
          process.exit(EXIT_CODES.VALIDATION_FAILED);
        }

        // Resolve inbox item
        const inboxItems = await loadInboxItems(ctx);
        const item = findInboxItemByRef(inboxItems, inboxRef);
        if (!item) {
          error(errors.reference.inboxNotFound(inboxRef));
          process.exit(EXIT_CODES.NOT_FOUND);
        }

        if (options.dryRun) {
          info(`Would create triage record for inbox item ${item._ulid.slice(0, 8)} with action: ${options.action}`);
          return;
        }

        const author = options.decidedBy || getAuthor(ctx.config?.identity?.author);
        const evidenceRefs = options.evidence
          ? options.evidence.map((r: string) => r.startsWith("@") ? r : `@${r}`)
          : [];

        const record: LoadedTriageRecord = {
          _ulid: ulid(),
          inbox_ref: item._ulid,
          item_snapshot: item.text,
          status: "triaged",
          action: options.action as TriageAction,
          reasoning: options.reasoning,
          decided_by: author,
          evidence_refs: evidenceRefs,
          created_at: new Date().toISOString(),
        };

        await saveTriageRecord(ctx, record);
        await commitIfShadow(
          ctx.shadow,
          "triage-record",
          record._ulid.slice(0, 8),
          options.action,
        );

        // AC: @triage-cli-commands ac-11 — JSON output
        // AC: @trait-json-output ac-1, ac-2, ac-4, ac-5
        success(`Recorded triage decision: ${record._ulid.slice(0, 8)}`, { record });
      } catch (err) {
        error("Failed to record triage decision", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec triage list
  // AC: @triage-cli-commands ac-2, ac-3
  triage
    .command("list")
    .description("List triage records")
    .option("--status <status>", "Filter by status (pending, triaged, acted_on)")
    .option("--action <action>", "Filter by action")
    .option("--limit <n>", "Limit results")
    .option("--count", "Show only the count")
    .action(async (options) => {
      try {
        const ctx = await initContext();
        let records = await loadTriageRecords(ctx);

        // AC: @triage-cli-commands ac-3 — status filter
        // AC: @trait-filterable-list ac-1
        if (options.status) {
          records = records.filter((r) => r.status === options.status);
        }

        if (options.action) {
          records = records.filter((r) => r.action === options.action);
        }

        // Sort by created_at desc (newest first)
        records.sort((a, b) => {
          return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
        });

        // AC: @trait-filterable-list ac-8
        if (options.count) {
          output({ count: records.length }, () => {
            console.log(records.length);
          });
          return;
        }

        if (options.limit) {
          const limit = parseInt(options.limit, 10);
          records = records.slice(0, limit);
        }

        // AC: @trait-json-output ac-1, ac-2
        output(records, () => {
          if (records.length === 0) {
            console.log("No triage records");
            return;
          }

          console.log(
            `Triage records (${records.length}):\n`,
          );

          // AC: @triage-cli-commands ac-2
          for (const record of records) {
            const snapshot = truncateText(record.item_snapshot, 50);
            const age = formatRelativeTime(record.created_at);
            const action = record.action ? ` [${record.action}]` : "";
            const decidedBy = record.decided_by ? ` by ${record.decided_by}` : "";
            console.log(`  ${record._ulid.slice(0, 8)} (${age}${decidedBy}) ${record.status}${action}`);
            console.log(`    ${snapshot}`);
            console.log("");
          }
        });
      } catch (err) {
        error("Failed to list triage records", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec triage act <triage-ref>
  // AC: @triage-cli-commands ac-4, ac-5, ac-6, ac-7, ac-8, ac-15, ac-16, ac-17
  markMutating(triage.command("act <triage-ref>"))
    .description("Execute a triage decision")
    .option("--dry-run", "Show what would happen without executing")
    .action(async (triageRef: string, options) => {
      try {
        const ctx = await initContext();
        const records = await loadTriageRecords(ctx);
        const record = resolveTriageRef(triageRef, records);

        // AC: @triage-cli-commands ac-15 — already acted on
        // AC: @trait-error-guidance ac-1, ac-2
        if (record.status === "acted_on") {
          error(`Triage record ${record._ulid.slice(0, 8)} has already been acted on. No further action is possible.`);
          process.exit(EXIT_CODES.VALIDATION_FAILED);
        }

        // AC: @triage-cli-commands ac-16 — no decision yet
        // AC: @trait-error-guidance ac-1, ac-2
        if (record.status === "pending") {
          error(`Triage record ${record._ulid.slice(0, 8)} has no decision yet. Record a decision first with: kspec triage record <inbox-ref> --action <action> --reasoning <text>`);
          process.exit(EXIT_CODES.VALIDATION_FAILED);
        }

        // AC: @triage-cli-commands ac-17 — dry run
        if (options.dryRun) {
          info(`Dry run for triage record ${record._ulid.slice(0, 8)}:`);
          await executeTriageAction(record, ctx, true);
          return;
        }

        // Execute the action
        const result = await executeTriageAction(record, ctx, false);

        // Transition to acted_on
        record.status = "acted_on";
        record.acted_at = new Date().toISOString();
        if (result.resultRef) {
          record.result_ref = result.resultRef;
        }
        record.updated_at = new Date().toISOString();

        await saveTriageRecord(ctx, record);
        await commitIfShadow(
          ctx.shadow,
          "triage-act",
          record._ulid.slice(0, 8),
          record.action,
        );

        success(`Acted on triage record: ${record._ulid.slice(0, 8)} (${record.action})`, { record });
      } catch (err) {
        error("Failed to act on triage record", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec triage override <triage-ref>
  // AC: @triage-cli-commands ac-12
  markMutating(triage.command("override <triage-ref>"))
    .description("Override an existing triage decision")
    .requiredOption("--action <action>", "New action (promote, delete, defer, spec-gap, duplicate)")
    .requiredOption("--reasoning <text>", "Reasoning for the override")
    .option("--override-by <author>", "Who is overriding")
    .action(async (triageRef: string, options) => {
      try {
        const ctx = await initContext();
        const records = await loadTriageRecords(ctx);
        const record = resolveTriageRef(triageRef, records);

        // Validate action
        const validActions = ["promote", "delete", "defer", "spec-gap", "duplicate"];
        if (!validActions.includes(options.action)) {
          error(`Invalid action: ${options.action}. Must be one of: ${validActions.join(", ")}`);
          process.exit(EXIT_CODES.VALIDATION_FAILED);
        }

        const overrideBy = options.overrideBy || getAuthor(ctx.config?.identity?.author);

        // AC: @triage-cli-commands ac-12
        record.override_reasoning = options.reasoning;
        record.override_by = overrideBy;
        record.override_at = new Date().toISOString();
        record.action = options.action as TriageAction;

        // Ensure status is triaged (for re-acting after override)
        if (record.status === "acted_on") {
          record.status = "triaged";
        }

        await saveTriageRecord(ctx, record);
        await commitIfShadow(
          ctx.shadow,
          "triage-override",
          record._ulid.slice(0, 8),
          options.action,
        );

        success(`Overrode triage decision: ${record._ulid.slice(0, 8)} → ${options.action}`, { record });
      } catch (err) {
        error("Failed to override triage decision", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec triage export
  // AC: @triage-cli-commands ac-13, ac-14
  triage
    .command("export")
    .description("Export triage decisions for agent handoff")
    .requiredOption("--format <format>", "Export format (context, json)")
    .option("--status <status>", "Filter by status")
    .action(async (options) => {
      try {
        const ctx = await initContext();
        let records = await loadTriageRecords(ctx);

        if (options.status) {
          records = records.filter((r) => r.status === options.status);
        }

        if (options.format === "json") {
          // AC: @triage-cli-commands ac-14
          // AC: @trait-json-output ac-1, ac-2, ac-5
          console.log(JSON.stringify(records, null, 2));
        } else if (options.format === "context") {
          // AC: @triage-cli-commands ac-13
          if (records.length === 0) {
            console.log("No triage decisions recorded.");
            return;
          }
          console.log("# Triage Decisions\n");
          for (const record of records) {
            console.log(formatTriageContext(record));
          }
        } else {
          error(`Invalid format: ${options.format}. Must be one of: context, json`);
          process.exit(EXIT_CODES.VALIDATION_FAILED);
        }
      } catch (err) {
        error("Failed to export triage records", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec triage start
  // AC: @triage-cli-commands ac-9, ac-10
  markMutating(triage.command("start"))
    .description("Start interactive triage of inbox items")
    .action(async () => {
      try {
        const ctx = await initContext();
        const inboxItems = await loadInboxItems(ctx);
        const existingRecords = await loadTriageRecords(ctx);

        // Find untriaged items (no existing triage record)
        const triagedInboxRefs = new Set(existingRecords.map((r) => r.inbox_ref));
        const untriaged = inboxItems.filter((item) => !triagedInboxRefs.has(item._ulid));

        if (untriaged.length === 0) {
          info("No untriaged inbox items");
          return;
        }

        console.log(`\nInteractive triage: ${untriaged.length} item(s) to review\n`);
        console.log("Actions: promote, delete, defer, spec-gap, duplicate, skip\n");

        const validActions = ["promote", "delete", "defer", "spec-gap", "duplicate", "skip"];
        let triaged = 0;

        // Use a single readline interface for the entire interactive session
        // to avoid stdin consumption issues when each prompt creates/destroys
        const rl = readline.createInterface({
          input: process.stdin,
          output: process.stdout,
        });

        const askQuestion = (question: string): Promise<string | null> => {
          return new Promise((resolve) => {
            rl.question(question, (answer) => {
              resolve(answer.trim());
            });
            // Handle close (Ctrl+C or EOF)
            rl.once("close", () => {
              resolve(null);
            });
          });
        };

        // AC: @triage-cli-commands ac-9 — present items one at a time
        for (const item of untriaged) {
          console.log("─".repeat(60));
          console.log(`Item: ${item._ulid.slice(0, 8)} (${formatRelativeTime(item.created_at)})`);
          if (item.tags.length > 0) {
            console.log(`Tags: ${item.tags.join(", ")}`);
          }
          if (item.added_by) {
            console.log(`Added by: ${item.added_by}`);
          }
          console.log("");
          console.log(item.text);
          console.log("");

          // AC: @triage-cli-commands ac-10 — Ctrl+C preserves committed records
          const action = await askQuestion("Action (promote/delete/defer/spec-gap/duplicate/skip): ");

          if (action === null) {
            // Ctrl+C or closed input
            console.log(`\nTriage interrupted. ${triaged} record(s) saved.`);
            rl.close();
            return;
          }

          if (!action || action === "skip") {
            console.log("Skipped\n");
            continue;
          }

          if (!validActions.includes(action)) {
            console.log(`Invalid action: ${action}. Skipping.\n`);
            continue;
          }

          const reasoning = await askQuestion("Reasoning: ");

          if (reasoning === null) {
            console.log(`\nTriage interrupted. ${triaged} record(s) saved.`);
            rl.close();
            return;
          }

          if (!reasoning) {
            console.log("Reasoning required. Skipping.\n");
            continue;
          }

          const author = getAuthor(ctx.config?.identity?.author);

          const record: LoadedTriageRecord = {
            _ulid: ulid(),
            inbox_ref: item._ulid,
            item_snapshot: item.text,
            status: "triaged",
            action: action as TriageAction,
            reasoning,
            decided_by: author,
            evidence_refs: [],
            created_at: new Date().toISOString(),
          };

          await saveTriageRecord(ctx, record);
          await commitIfShadow(
            ctx.shadow,
            "triage-record",
            record._ulid.slice(0, 8),
            action,
          );

          triaged++;
          console.log(`Recorded: ${record._ulid.slice(0, 8)} → ${action}\n`);
        }

        rl.close();
        console.log(`\nTriage complete. ${triaged} record(s) created.`);
      } catch (err) {
        error("Failed to start interactive triage", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec triage get <triage-ref>
  triage
    .command("get <triage-ref>")
    .description("Show details of a triage record")
    .action(async (triageRef: string) => {
      try {
        const ctx = await initContext();
        const records = await loadTriageRecords(ctx);
        const record = resolveTriageRef(triageRef, records);

        output(record, () => {
          console.log(`ULID:        ${record._ulid}`);
          console.log(`Inbox ref:   ${record.inbox_ref}`);
          console.log(`Status:      ${record.status}`);
          if (record.action) console.log(`Action:      ${record.action}`);
          if (record.reasoning) console.log(`Reasoning:   ${record.reasoning}`);
          if (record.decided_by) console.log(`Decided by:  ${record.decided_by}`);
          if (record.evidence_refs.length > 0) {
            console.log(`Evidence:    ${record.evidence_refs.join(", ")}`);
          }
          console.log(`Created:     ${record.created_at} (${formatRelativeTime(record.created_at)})`);
          if (record.updated_at) {
            console.log(`Updated:     ${record.updated_at}`);
          }
          if (record.override_reasoning) {
            console.log("");
            console.log("Override:");
            console.log(`  Reasoning: ${record.override_reasoning}`);
            if (record.override_by) console.log(`  By:        ${record.override_by}`);
            if (record.override_at) console.log(`  At:        ${record.override_at}`);
          }
          if (record.acted_at) {
            console.log("");
            console.log(`Acted at:    ${record.acted_at}`);
            if (record.result_ref) console.log(`Result ref:  ${record.result_ref}`);
          }
          console.log("");
          console.log("Item snapshot:");
          console.log(record.item_snapshot);
        });
      } catch (err) {
        error("Failed to get triage record", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
}

