  const ulid2 = addInboxItem("Count test item beta");
  recordTriage(ulid2, "defer", "defer");

  // Verify records exist
  const allRecords = kspecJson<Array<{ _ulid: string; inbox_ref: string }>>(
    "triage list",
    tempDir,
  );
  // If ULID prefix collision caused upsert, we may only have 1 record
  // In that case, adjust expectation
  const expectedCount = allRecords.length;

  const result = kspecJson<{ count: number }>(
    "triage list --count",
    tempDir,
  );
  expect(result.count).toBe(expectedCount);
  expect(result.count).toBeGreaterThanOrEqual(1);
});

