   644→            status.implementation === "verified"
   645→              ? chalk.green
   646→              : status.implementation === "implemented"
   647→                ? chalk.cyan
   648→                : status.implementation === "in_progress"
   649→                  ? chalk.yellow
   650→                  : chalk.gray;
