  });

  // AC: @trait-json-output ac-1
  it("should output records as valid JSON array", () => {
    const ulid1 = addInboxItem("JSON list test");
    recordTriage(ulid1, "promote", "test");

    const records = kspecJson<Array<{ _ulid: string; status: string }>>(
      "triage list",
