    const acted = records.find((r) => r._ulid === record._ulid);
    expect(acted).toBeDefined();
    expect(acted!.status).toBe("acted_on");
    expect(acted!.acted_at).toBeDefined();
    expect(acted!.result_ref).toBeDefined();
