    },
    {
      "id": "ac-3",
      "given": "a POST request is sent to /api/triage with inbox_ref, action, reasoning\n",
      "when": "the referenced inbox item exists\n",
      "then": "creates a TriageRecord with item_snapshot, returns the record,\nand broadcasts triage:updates via WebSocket\n"
    },
    {
      "id": "ac-4",
      "given": "a PUT request is sent to /api/triage/:ref with override fields\n",
