 14→  private configDir: string;
 15→  private pidFilePath: string;
 16→  private portFilePath: string;
 17→
 18→  constructor(configDir: string = join(homedir(), '.config', 'kspec')) {
 19→    this.configDir = configDir;
 20→    this.pidFilePath = join(configDir, 'daemon.pid');
 21→    this.portFilePath = join(configDir, 'daemon.port');
 22→  }
 23→
 24→  /**
 25→   * AC: @multi-directory-daemon ac-9b
 26→   * Creates config directory with mode 0755 if it doesn't exist
 27→   */
 28→  private ensureConfigDir(): void {
 29→    if (!existsSync(this.configDir)) {
 30→      mkdirSync(this.configDir, { recursive: true, mode: 0o755 });
 31→    }
 32→  }
 33→
 34→  /**
 35→   * AC: @multi-directory-daemon ac-9, ac-10b
 36→   * Writes current process PID to ~/.config/kspec/daemon.pid
 37→   * Creates parent directory if it doesn't exist.
 38→   * Uses exclusive file creation flag to prevent concurrent daemon starts.
 39→   */
 40→  writePid(): void {
 41→    this.ensureConfigDir();
 42→
 43→    // AC: @multi-directory-daemon ac-10b
 44→    // Use O_CREAT | O_EXCL flags for atomic file creation
 45→    // This prevents race conditions between concurrent daemon starts
 46→    try {
 47→      const fd = openSync(this.pidFilePath, constants.O_CREAT | constants.O_EXCL | constants.O_WRONLY, 0o644);
 48→      try {
 49→        writeFileSync(fd, process.pid.toString(), 'utf-8');
 50→      } finally {
 51→        closeSync(fd);
 52→      }
 53→    } catch (err: unknown) {
 54→      if (err instanceof Error && 'code' in err && (err as NodeJS.ErrnoException).code === 'EEXIST') {
 55→        // File already exists - check if daemon is actually running
 56→        if (this.isDaemonRunning()) {
 57→          throw new Error('Daemon already running');
 58→        }
 59→        // Stale PID file - remove it and retry
 60→        this.remove();
 61→        const fd = openSync(this.pidFilePath, constants.O_CREAT | constants.O_EXCL | constants.O_WRONLY, 0o644);
 62→        try {
 63→          writeFileSync(fd, process.pid.toString(), 'utf-8');
 64→        } finally {
 65→          closeSync(fd);
 66→        }
 67→      } else {
