154→   * Checks if daemon is currently running based on PID file
155→   */
156→  isDaemonRunning(): boolean {
157→    const pid = this.readPid();
158→    if (pid === null) {
159→      return false;
160→    }
161→    return this.isProcessRunning(pid);
162→  }
163→
164→  /**
165→   * Backwards compatibility: read() method maps to readPid()
166→   * @deprecated Use readPid() instead
167→   */
168→  read(): number | null {
