     1→/**
     2→ * Validation and Search API Routes
     3→ *
     4→ * REST endpoints for search and validation operations:
     5→ * - GET /api/search?q=query - Search across all items/tasks/inbox/meta
     6→ * - GET /api/validate - Run full validation
     7→ * - GET /api/alignment - Get alignment stats and warnings
     8→ *
     9→ * AC Coverage:
    10→ * - ac-19: GET /api/search?q=query searches across all entities
    11→ * - ac-20: GET /api/validate returns ValidationResult
    12→ * - ac-21: GET /api/alignment returns AlignmentIndex stats
    13→ */
    14→
    15→import { Elysia, t } from 'elysia';
    16→import {
    17→  initContext,
    18→  buildIndexes,
    19→  loadInboxItems,
    20→  loadMetaContext,
    21→  validate,
    22→  AlignmentIndex,
    23→  type LoadedSpecItem,
    24→  type LoadedTask,
    25→  type LoadedInboxItem,
    26→} from '../../parser/index.js';
    27→import type {
    28→  LoadedAgent,
    29→  LoadedWorkflow,
    30→  LoadedObservation,
    31→  LoadedConvention,
    32→} from '../../parser/meta.js';
    33→import { grepItem } from '../../utils/grep.js';
    34→
    35→interface ValidationRouteOptions {}
    36→
    37→export function createValidationRoutes(options: ValidationRouteOptions = {}) {
    38→  // No closure-scoped kspecDir needed - comes from middleware
    39→
    40→  return new Elysia({ prefix: '/api' })
    41→    // AC: @api-contract ac-19 - Search across all entities
    42→    .get(
    43→      '/search',
    44→      async ({ query, projectContext }) => {
    45→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
    46→        const ctx = await initContext(projectContext.path);
    47→        const { tasks, items } = await buildIndexes(ctx);
    48→
    49→        const pattern = query.q;
    50→        if (!pattern) {
    51→          return {
    52→            results: [],
    53→            total: 0,
    54→          };
    55→        }
    56→
    57→        const limit = query.limit ? parseInt(query.limit, 10) : 50;
    58→
    59→        interface SearchResult {
    60→          type:
    61→            | 'item'
    62→            | 'task'
    63→            | 'inbox'
    64→            | 'observation'
    65→            | 'agent'
    66→            | 'workflow'
    67→            | 'convention';
    68→          ulid: string;
    69→          title: string;
    70→          matchedFields: string[];
    71→        }
    72→
    73→        const results: SearchResult[] = [];
    74→
    75→        // AC: @api-contract ac-19 - Search spec items
    76→        if (!query.tasksOnly) {
    77→          for (const item of items) {
    78→            // Apply type filter if provided
    79→            if (query.type && item.type !== query.type) continue;
    80→
    81→            const match = grepItem(item as unknown as Record<string, unknown>, pattern);
    82→            if (match) {
    83→              results.push({
    84→                type: 'item',
    85→                ulid: item._ulid,
    86→                title: item.title,
    87→                matchedFields: match.matchedFields,
    88→              });
    89→            }
    90→          }
    91→        }
    92→
    93→        // AC: @api-contract ac-19 - Search tasks
    94→        if (!query.itemsOnly) {
    95→          for (const task of tasks) {
    96→            // Apply status filter if provided
    97→            if (query.status && task.status !== query.status) continue;
    98→
    99→            const match = grepItem(task as unknown as Record<string, unknown>, pattern);
   100→            if (match) {
   101→              results.push({
   102→                type: 'task',
   103→                ulid: task._ulid,
   104→                title: task.title,
   105→                matchedFields: match.matchedFields,
   106→              });
   107→            }
   108→          }
   109→        }
   110→
   111→        // AC: @api-contract ac-19 - Search inbox items
   112→        if (!query.itemsOnly && !query.tasksOnly) {
   113→          const inboxItems = await loadInboxItems(ctx);
   114→          for (const inboxItem of inboxItems) {
   115→            const match = grepItem(inboxItem as unknown as Record<string, unknown>, pattern);
   116→            if (match) {
   117→              results.push({
   118→                type: 'inbox',
   119→                ulid: inboxItem._ulid,
   120→                title: inboxItem.text,
   121→                matchedFields: match.matchedFields,
   122→              });
   123→            }
   124→          }
   125→        }
   126→
   127→        // AC: @api-contract ac-19 - Search meta entities
   128→        if (!query.itemsOnly && !query.tasksOnly) {
   129→          const metaCtx = await loadMetaContext(ctx);
   130→
   131→          // Search observations
   132→          for (const observation of metaCtx.observations) {
   133→            const match = grepItem(observation as unknown as Record<string, unknown>, pattern);
   134→            if (match) {
   135→              results.push({
   136→                type: 'observation',
   137→                ulid: observation._ulid,
   138→                title: observation.content,
   139→                matchedFields: match.matchedFields,
   140→              });
   141→            }
   142→          }
   143→
   144→          // Search agents
   145→          for (const agent of metaCtx.agents) {
   146→            const match = grepItem(agent as unknown as Record<string, unknown>, pattern);
   147→            if (match) {
   148→              results.push({
   149→                type: 'agent',
   150→                ulid: agent._ulid,
   151→                title: `${agent.id} - ${agent.name}`,
   152→                matchedFields: match.matchedFields,
   153→              });
   154→            }
   155→          }
   156→
   157→          // Search workflows
   158→          for (const workflow of metaCtx.workflows) {
   159→            const match = grepItem(workflow as unknown as Record<string, unknown>, pattern);
   160→            if (match) {
   161→              results.push({
   162→                type: 'workflow',
   163→                ulid: workflow._ulid,
   164→                title: workflow.id,
   165→                matchedFields: match.matchedFields,
   166→              });
   167→            }
   168→          }
   169→
   170→          // Search conventions
   171→          for (const convention of metaCtx.conventions) {
   172→            const match = grepItem(convention as unknown as Record<string, unknown>, pattern);
   173→            if (match) {
   174→              results.push({
   175→                type: 'convention',
   176→                ulid: convention._ulid,
   177→                title: convention.domain,
   178→                matchedFields: match.matchedFields,
   179→              });
   180→            }
   181→          }
   182→        }
   183→
   184→        // Apply limit
   185→        const limitedResults = results.slice(0, limit);
   186→
   187→        // AC: @api-contract ac-19 - Return search results with matched fields
   188→        return {
   189→          results: limitedResults,
   190→          total: results.length,
   191→          showing: limitedResults.length,
   192→        };
   193→      },
   194→      {
   195→        query: t.Object({
   196→          q: t.Optional(t.String()),
   197→          type: t.Optional(t.String()),
   198→          status: t.Optional(t.String()),
   199→          itemsOnly: t.Optional(t.String()),
   200→          tasksOnly: t.Optional(t.String()),
   201→          limit: t.Optional(t.String()),
   202→        }),
   203→      }
   204→    )
   205→
   206→    // AC: @api-contract ac-20 - Run full validation
   207→    .get('/validate', async ({ projectContext }) => {
   208→      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   209→      const ctx = await initContext(projectContext.path);
   210→
   211→      // AC: @api-contract ac-20 - Run validation and return ValidationResult
   212→      const result = await validate(ctx);
   213→
   214→      return {
   215→        valid: result.valid,
   216→        schemaErrors: result.schemaErrors,
   217→        refErrors: result.refErrors,
   218→        refWarnings: result.refWarnings,
   219→        orphans: result.orphans,
   220→        completenessWarnings: result.completenessWarnings,
   221→        traitCycles: result.traitCycles,
   222→      };
   223→    })
   224→
   225→    // AC: @api-contract ac-21 - Get alignment stats and warnings
   226→    .get('/alignment', async ({ projectContext }) => {
   227→      // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   228→      const ctx = await initContext(projectContext.path);
   229→      const { tasks, items, refIndex } = await buildIndexes(ctx);
   230→
   231→      // AC: @api-contract ac-21 - Create AlignmentIndex and get stats
   232→      const alignIndex = new AlignmentIndex(tasks, items);
   233→      alignIndex.buildLinks(refIndex);
   234→
   235→      const stats = alignIndex.getStats();
   236→      const warnings = alignIndex.findAlignmentWarnings();
   237→
   238→      return {
   239→        stats: {
   240→          totalSpecs: stats.totalSpecs,
   241→          specsWithTasks: stats.specsWithTasks,
   242→          alignedSpecs: stats.alignedSpecs,
   243→          orphanedSpecs: stats.orphanedSpecs,
   244→        },
   245→        warnings,
   246→      };
   247→    });
   248→}
   249→
