   114→          if (code === 'EACCES' || code === 'EPERM') {
   115→            return errorResponse(403, {
   116→              error: `Permission denied - cannot read ${body.path}`,
   117→            });
   118→          }
   119→
   120→          // Generic error
   121→          return errorResponse(500, {
   122→            error: message || 'Failed to register project',
   123→          });
   124→        }
   125→      },
   126→      {
   127→        body: t.Object({
   128→          path: t.String(),
   129→        }),
   130→      }
   131→    )
   132→
   133→    // AC: @multi-directory-daemon ac-30 - Unregister project
   134→    .delete('/:encodedPath', async ({ params, error: errorResponse }) => {
   135→      // AC: @multi-directory-daemon ac-30 - Decode path from URL parameter
   136→      const projectPath = decodeURIComponent(params.encodedPath);
   137→
   138→      // Validate project exists
   139→      if (!projectManager.hasProject(projectPath)) {
   140→        return errorResponse(404, {
   141→          error: `Project not registered: ${projectPath}`,
   142→        });
   143→      }
   144→
   145→      try {
   146→        // AC: @multi-directory-daemon ac-30 - Stop file watcher
   147→        await projectManager.stopWatcher(projectPath);
   148→
   149→        // AC: @multi-directory-daemon ac-30 - Unregister project
   150→        projectManager.unregisterProject(projectPath);
   151→
   152→        return {
   153→          success: true,
   154→          message: `Project unregistered: ${projectPath}`,
   155→        };
   156→      } catch (error: unknown) {
   157→        return errorResponse(500, {
   158→          error: error instanceof Error ? error.message : 'Failed to unregister project',
   159→        });
   160→      }
   161→    });
   162→}
