import { commitIfShadow } from '../../parser/shadow.js';
import type { PubSubManager } from '../websocket/pubsub';

interface TriageRouteOptions {
  pubsub: PubSubManager;
}

export function createTriageRoutes(options: TriageRouteOptions) {
  const { pubsub } = options;
  return new Elysia({ prefix: '/api/triage' })
    .get('/', async ({ query, projectContext }) => { ... })
    .post('/', async ({ body, error: errorResponse, projectContext }) => { ... }, { body: t.Object({...}) })
    .delete('/:ref', async ({ params, error: errorResponse, projectContext }) => { ... }, { params: t.Object({ ref: t.String() }) });
}
```

**Registration in `server.ts`** — add after the other routes:
```typescript
import { createTriageRoutes } from './routes/triage';
// ...
.use(createTriageRoutes({ pubsub: pubsubManager }))
```

---

### 2. Project Context Pattern (critical - every handler uses this)

Every handler destructures `projectContext` from middleware state and passes it to `initContext`:
```typescript
async ({ query, projectContext }) => {
  // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
  const ctx = await initContext(projectContext.path);
  // ... now use ctx for all parser calls
}
```

`projectContext` is automatically provided by the `projectContextMiddleware` (via `.derive()`). It is read from the `X-Kspec-Dir` request header or falls back to the startup project. **Never hardcode `kspecDir`.**

---

### 3. Error Handling Patterns

All errors use the destructured `error` renamed to `errorResponse`:

```typescript
async ({ params, body, error: errorResponse, projectContext }) => { ... }
```

**404 - Not Found** (for unknown ref):
```typescript
return errorResponse(404, {
  error: 'not_found',
  message: `Triage record reference "${params.ref}" not found`,
  suggestion: 'Use kspec triage list to find valid triage record references',
});
```

**400 - Validation Error** (for bad body/params):
```typescript
return errorResponse(400, {
  error: 'validation_error',
  details: [
    {
      field: 'action',
      message: 'Action must be one of: promote, delete, defer, spec-gap, duplicate',
    },
  ],
});
```

**409 - Invalid Transition** (for state machine violations):
```typescript
return errorResponse(409, {
  error: 'invalid_transition',
  message: 'Triage record has already been acted on',
  current: record.status,
  valid_transitions: ['triaged'],  // only override is valid after acted_on
});
```

**422 - Not used directly** — Elysia body schema validation failures produce automatic 422s, but in-handler validation uses 400.

---

### 4. PubSub Broadcast Pattern

After every mutation, broadcast to the relevant topic scoped to the project:

```typescript
pubsub.broadcast('triage:updates', 'triage_record_created', {
  ulid: record._ulid,
  inbox_ref: record.inbox_ref,
}, projectContext.path);
```

Signature: `broadcast(topic: string, event: string, data: Record<string, unknown>, projectPath?: string)`

- The `projectPath` argument ensures only WebSocket clients bound to the same project receive the event.
- Topic naming convention: `<resource>:updates` (e.g., `inbox:updates`, `tasks:updates`, `triage:updates`)
- Event name convention: `<resource>_<action>` (e.g., `inbox_item_created`, `task_updated`, `triage_record_created`)

---

### 5. Pagination Pattern

Used in list endpoints (`GET /api/tasks/`, `GET /api/items/`):

```typescript
const total = filtered.length;
const offset = Number(query.offset) || 0;
const limit = Number(query.limit) || total;   // default: return all

const paginated = filtered.slice(offset, offset + limit);

return {
  items: paginated.map(...),
  total,
  offset,
  limit,
};
```

Query schema:
```typescript
{
  query: t.Object({
    status: t.Optional(t.Union([t.String(), t.Array(t.String())])),
    action: t.Optional(t.Union([t.String(), t.Array(t.String())])),
    limit: t.Optional(t.String()),
    offset: t.Optional(t.String()),
  }),
}
```

---

### 6. Request ID Header Pattern

There is **no per-request ID header** added by routes. The `ulid()` import from `ulidx` is used only in the WebSocket open handler (for `sessionId`) and in the PubSubManager (for `msg_id` in broadcast events). Route handlers do not set a `X-Request-Id` response header — this is not part of the current pattern.

---

### 7. Triage Library Functions (from parser)

All available from `../../parser/index.js` (which re-exports everything from `src/parser/yaml.ts`):

```typescript
import {
  initContext,
  loadTriageRecords,        // loadTriageRecords(ctx) → Promise<LoadedTriageRecord[]>
  saveTriageRecord,         // saveTriageRecord(ctx, record) → Promise<void> — upserts by _ulid then inbox_ref
  findTriageRecordByRef,    // findTriageRecordByRef(records, ref) → LoadedTriageRecord | undefined — ref can be full ULID or short prefix, with or without '@'
  findTriageRecordByInboxRef, // findTriageRecordByInboxRef(records, inboxRef) → LoadedTriageRecord | undefined
  loadInboxItems,           // for cross-referencing inbox items
  findInboxItemByRef,
  loadAllTasks,
  loadAllItems,
  ReferenceIndex,
  getAuthor,
  createObservation,        // used by spec-gap action
  saveObservation,
  createTask,               // used by promote action
  saveTask,
  deleteInboxItem,          // used by delete/duplicate actions
  type LoadedTriageRecord,
} from '../../parser/index.js';
import { commitIfShadow } from '../../parser/shadow.js';
```

The `executeTriageAction()` function in the CLI (`src/cli/commands/triage.ts`) can be lifted wholesale as a private helper in the route file — it already handles all 5 action types (promote, delete, defer, spec-gap, duplicate) and returns `{ resultRef?: string }`.

---

### 8. Triage Schema Types

From `src/schema/triage.ts`, exported through `src/schema/index.ts`:

```typescript
type TriageStatus = 'pending' | 'triaged' | 'acted_on'
type TriageAction = 'promote' | 'delete' | 'defer' | 'spec-gap' | 'duplicate'

interface LoadedTriageRecord extends TriageRecord {
  _ulid: string;
  inbox_ref: string;          // ULID of the source inbox item
  item_snapshot: string;      // Text of inbox item at triage time (preserved after deletion)
  status: TriageStatus;
  action?: TriageAction;
  reasoning?: string;
  decided_by?: string;
  evidence_refs: string[];    // ref strings like '@spec-item'
  override_reasoning?: string;
  override_by?: string;
  override_at?: string;       // ISO datetime
  acted_at?: string;          // ISO datetime, required when status === 'acted_on'
  result_ref?: string;        // e.g., '@task-xyz' created by promote/spec-gap
  created_at: string;         // ISO datetime
  updated_at?: string;        // ISO datetime, set by saveTriageRecord on every mutation
  _sourceFile?: string;       // runtime only
}
```

State machine constraints (enforced by `superRefine` in schema):
- `triaged` requires `action`, `reasoning`, `decided_by`
- `acted_on` requires `acted_at` + all `triaged` fields

---

### 9. Shadow Commit Pattern

After every mutation:
```typescript
await commitIfShadow(ctx.shadow, `triage: record ${record._ulid.slice(0, 8)} as ${record.action}`);
// or for act:
await commitIfShadow(ctx.shadow, `triage: act ${record._ulid.slice(0, 8)}`);
// or for override:
await commitIfShadow(ctx.shadow, `triage: override ${record._ulid.slice(0, 8)}`);
```

The CLI uses a 4-arg form: `commitIfShadow(ctx.shadow, "triage-record", ulid, action)` but the route files consistently use the 2-arg string form matching the inbox/tasks pattern: `commitIfShadow(ctx.shadow, "inbox: add item " + item._ulid)`.

---

### 10. AC Annotation Convention

Every handler and significant block gets an inline comment:
```typescript
// AC: @triage-api ac-1 - List triage records with pagination
// AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
```

And the file header has a doc comment listing all covered ACs.

---

### 11. Recommended Route Structure for `/api/triage`

Based on the CLI (`record`, `list`, `act`, `override`, `export`, `get`), the daemon routes should be:

```
GET    /api/triage                  — list records (pagination, status/action filters)
POST   /api/triage                  — record decision (body: inbox_ref, action, reasoning, decided_by, evidence_refs)
GET    /api/triage/:ref             — get single record
POST   /api/triage/:ref/act         — execute action (transitions triaged → acted_on)
POST   /api/triage/:ref/override    — override decision (updates action, sets override_* fields)
GET    /api/triage/export           — export records (query: format=context|json, status filter)
```

State-change routes (`/act`, `/override`) need the 409 invalid-transition pattern. The `record` POST creates via `saveTriageRecord` (which upserts). The `act` POST reuses `executeTriageAction` logic then calls `saveTriageRecord` again with `status: 'acted_on'`.

