import * as readline from "node:readline";
import { ulid } from "ulid";
import type { Command } from "commander";
import { markMutating } from "../command-annotations.js";
import {
  createObservation,
  createTask,
  deleteInboxItem,
  findInboxItemByRef,
  getAuthor,
  initContext,
  type LoadedInboxItem,
  type LoadedTriageRecord,
  loadAllItems,
  loadAllTasks,
  loadInboxItems,
  loadTriageRecords,
  ReferenceIndex,
  saveObservation,
  saveTask,
  saveTriageRecord,
  findTriageRecordByRef,
} from "../../parser/index.js";
import { commitIfShadow } from "../../parser/shadow.js";
import type { TriageAction, TriageRecord } from "../../schema/index.js";
import { errors } from "../../strings/index.js";
import { formatRelativeTime as formatRelativeTimeUtil } from "../../utils/time.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, info, output, success } from "../output.js";

/**
 * Format relative time for display
 */
function formatRelativeTime(dateStr: string): string {
  return formatRelativeTimeUtil(new Date(dateStr));
}

/**
 * Resolve triage record ref with error handling
 */
function resolveTriageRef(
  ref: string,
  records: LoadedTriageRecord[],
): LoadedTriageRecord {
  const record = findTriageRecordByRef(records, ref);
  if (!record) {
    error(`Triage record not found: ${ref}`);
    process.exit(EXIT_CODES.NOT_FOUND);
  }
  return record;
}

/**
 * Truncate text for display
 */
function truncateText(text: string, maxLen: number = 60): string {
  const firstLine = text.split("\n")[0].trim();
  if (firstLine.length <= maxLen) return firstLine;
  return `${firstLine.slice(0, maxLen - 3)}...`;
}

/**
 * Execute a triage action
 * AC: @triage-cli-commands ac-4, ac-5, ac-6, ac-7, ac-8
 */
async function executeTriageAction(
  record: LoadedTriageRecord,
  ctx: Awaited<ReturnType<typeof initContext>>,
  dryRun: boolean = false,
): Promise<{ resultRef?: string }> {
  const action = record.action;
  if (!action) {
    error("Record has no action to execute");
    process.exit(EXIT_CODES.VALIDATION_FAILED);
  }

  switch (action) {
    case "promote": {
      // AC: @triage-cli-commands ac-4
      if (dryRun) {
        info(`Would create task from inbox item snapshot: "${truncateText(record.item_snapshot)}"`);
        return {};
      }
      const task = createTask({
        title: record.item_snapshot.split("\n")[0].slice(0, 100),
        type: "task",
        priority: 3,
        spec_ref: null,
        tags: [],
        description: record.item_snapshot,
      });
      await saveTask(ctx, task);
      const tasks = await loadAllTasks(ctx);
      const items = await loadAllItems(ctx);
      const index = new ReferenceIndex(tasks, items);
      const taskRef = `@${index.shortUlid(task._ulid)}`;
      info(`Created task: ${taskRef} - ${task.title}`);
      return { resultRef: taskRef };
    }

    case "delete": {
      // AC: @triage-cli-commands ac-5
      if (dryRun) {
        info(`Would delete inbox item: ${record.inbox_ref.slice(0, 8)}`);
        return {};
      }
      const inboxItems = await loadInboxItems(ctx);
      const inboxItem = findInboxItemByRef(inboxItems, record.inbox_ref);
      if (inboxItem) {
        await deleteInboxItem(ctx, inboxItem._ulid);
        info(`Deleted inbox item: ${record.inbox_ref.slice(0, 8)}`);
      }
      return {};
    }

    case "defer": {
      // AC: @triage-cli-commands ac-6
      if (dryRun) {
        info(`Would defer: no side effects beyond recording the deferral`);
        return {};
      }
      return {};
    }

    case "spec-gap": {
      // AC: @triage-cli-commands ac-7
      if (dryRun) {
        info(`Would create spec-gap observation from: "${truncateText(record.item_snapshot)}"`);
        return {};
      }
      const content = `[spec-gap] ${record.item_snapshot}\n\nReasoning: ${record.reasoning || ""}`;
      const observation = createObservation("question", content, {
        configAuthor: ctx.config?.identity?.author,
      });
      await saveObservation(ctx, observation);
      const obsRef = `@${observation._ulid.slice(0, 8)}`;
      info(`Created spec-gap observation: ${obsRef}`);
      return { resultRef: obsRef };
    }

    case "duplicate": {
      // AC: @triage-cli-commands ac-8
      if (dryRun) {
        info(`Would delete duplicate inbox item: ${record.inbox_ref.slice(0, 8)}`);
        return {};
      }
      const dupItems = await loadInboxItems(ctx);
      const dupItem = findInboxItemByRef(dupItems, record.inbox_ref);
      if (dupItem) {
        await deleteInboxItem(ctx, dupItem._ulid);
        info(`Deleted duplicate inbox item: ${record.inbox_ref.slice(0, 8)}`);
      }
      return {};
    }
  }
}

/**
 * Format a triage record for context export
 * AC: @triage-cli-commands ac-13
 */
function formatTriageContext(record: TriageRecord): string {
  const lines: string[] = [];
  lines.push(`### ${record._ulid.slice(0, 8)} — ${truncateText(record.item_snapshot, 80)}`);
  lines.push("");
  lines.push(`**Item:** ${record.item_snapshot}`);
  lines.push(`**Status:** ${record.status}`);
  if (record.action) lines.push(`**Action:** ${record.action}`);
  if (record.reasoning) lines.push(`**Reasoning:** ${record.reasoning}`);
  if (record.decided_by) lines.push(`**Decided by:** ${record.decided_by}`);
  if (record.evidence_refs.length > 0) {
    lines.push(`**Evidence:** ${record.evidence_refs.join(", ")}`);
  }
  if (record.override_reasoning) {
    lines.push(`**Override:** ${record.override_reasoning} (by ${record.override_by || "unknown"})`);
  }
  if (record.acted_at) {
    lines.push(`**Acted at:** ${record.acted_at}`);
    if (record.result_ref) lines.push(`**Result:** ${record.result_ref}`);
  }
  lines.push("");
  return lines.join("\n");
}

/**
 * Register the 'triage' command group
 * AC: @triage-cli-commands ac-1 through ac-17
 */
export function registerTriageCommands(program: Command): void {
  const triage = program
    .command("triage")
    .description("Record, review, and act on triage decisions");

  // kspec triage record <inbox-ref>
  // AC: @triage-cli-commands ac-1, ac-11
  markMutating(triage.command("record <inbox-ref>"))
    .description("Record a triage decision for an inbox item")
    .requiredOption("--action <action>", "Triage action (promote, delete, defer, spec-gap, duplicate)")
    .requiredOption("--reasoning <text>", "Reasoning for the decision")
    .option("--decided-by <author>", "Who made the decision")
    .option("--evidence <refs...>", "Evidence references")
    .option("--dry-run", "Show what would happen without making changes")
    .addHelpText(
      "after",
      `
Examples:
  $ kspec triage record @ref --action promote --reasoning "clear feature request"
  $ kspec triage record @ref --action defer --reasoning "needs more discussion"`,
    )
    .action(async (inboxRef: string, options) => {
      try {
        const ctx = await initContext();

        // Validate action
