        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec triage start
  // AC: @triage-cli-commands ac-9, ac-10
  markMutating(triage.command("start"))
    .description("Start interactive triage of inbox items")
    .action(async () => {
      try {
        const ctx = await initContext();
        const inboxItems = await loadInboxItems(ctx);
        const existingRecords = await loadTriageRecords(ctx);

        // Find untriaged items (no existing triage record)
        const triagedInboxRefs = new Set(existingRecords.map((r) => r.inbox_ref));
        const untriaged = inboxItems.filter((item) => !triagedInboxRefs.has(item._ulid));

        if (untriaged.length === 0) {
          info("No untriaged inbox items");
          return;
        }

        console.log(`\nInteractive triage: ${untriaged.length} item(s) to review\n`);
        console.log("Actions: promote, delete, defer, spec-gap, duplicate, skip\n");

        const validActions = ["promote", "delete", "defer", "spec-gap", "duplicate", "skip"];
        let triaged = 0;

        // Use a line-buffering approach for interactive prompts.
        // readline.question() has issues with piped stdin because the close
        // event can fire before subsequent question() calls process buffered lines.
        // Instead, we collect lines via the 'line' event and read from the buffer.
        const lineBuffer: string[] = [];
        let lineResolve: ((value: string | null) => void) | null = null;
        let inputClosed = false;

        const rl = readline.createInterface({
          input: process.stdin,
          output: process.stdout,
          terminal: false,
        });

        rl.on("line", (line) => {
          if (lineResolve) {
            const resolve = lineResolve;
            lineResolve = null;
            resolve(line.trim());
          } else {
            lineBuffer.push(line.trim());
          }
        });

        rl.on("close", () => {
          inputClosed = true;
          if (lineResolve) {
            const resolve = lineResolve;
            lineResolve = null;
            resolve(null);
          }
        });

        const askQuestion = (question: string): Promise<string | null> => {
          process.stdout.write(question);
          if (lineBuffer.length > 0) {
            return Promise.resolve(lineBuffer.shift()!);
          }
          if (inputClosed) return Promise.resolve(null);
          return new Promise((resolve) => {
            lineResolve = resolve;
          });
        };

        // AC: @triage-cli-commands ac-9 — present items one at a time
        for (const item of untriaged) {
          console.log("─".repeat(60));
          console.log(`Item: ${item._ulid.slice(0, 8)} (${formatRelativeTime(item.created_at)})`);
          if (item.tags.length > 0) {
            console.log(`Tags: ${item.tags.join(", ")}`);
          }
          if (item.added_by) {
            console.log(`Added by: ${item.added_by}`);
          }
          console.log("");
          console.log(item.text);
          console.log("");

          // AC: @triage-cli-commands ac-10 — Ctrl+C preserves committed records
          const action = await askQuestion("Action (promote/delete/defer/spec-gap/duplicate/skip): ");

          if (action === null) {
            // Ctrl+C or closed input
            console.log(`\nTriage interrupted. ${triaged} record(s) saved.`);
            rl.close();
            return;
          }

          if (!action || action === "skip") {
            console.log("Skipped\n");
            continue;
          }

          if (!validActions.includes(action)) {
            console.log(`Invalid action: ${action}. Skipping.\n`);
            continue;
          }

          const reasoning = await askQuestion("Reasoning: ");

          if (reasoning === null) {
            console.log(`\nTriage interrupted. ${triaged} record(s) saved.`);
            rl.close();
            return;
          }

          if (!reasoning) {
            console.log("Reasoning required. Skipping.\n");
            continue;
          }

          const author = getAuthor(ctx.config?.identity?.author);

          const record: LoadedTriageRecord = {
            _ulid: ulid(),
            inbox_ref: item._ulid,
            item_snapshot: item.text,
            status: "triaged",
            action: action as TriageAction,
            reasoning,
            decided_by: author,
            evidence_refs: [],
            created_at: new Date().toISOString(),
          };

          await saveTriageRecord(ctx, record);
          await commitIfShadow(
            ctx.shadow,
            "triage-record",
            record._ulid.slice(0, 8),
            action,
          );

          triaged++;
          console.log(`Recorded: ${record._ulid.slice(0, 8)} → ${action}\n`);
        }

        rl.close();
        console.log(`\nTriage complete. ${triaged} record(s) created.`);
      } catch (err) {
        error("Failed to start interactive triage", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });

  // kspec triage get <triage-ref>
  triage
    .command("get <triage-ref>")
    .description("Show details of a triage record")
    .action(async (triageRef: string) => {
      try {
        const ctx = await initContext();
        const records = await loadTriageRecords(ctx);
        const record = resolveTriageRef(triageRef, records);

        output(record, () => {
          console.log(`ULID:        ${record._ulid}`);
          console.log(`Inbox ref:   ${record.inbox_ref}`);
          console.log(`Status:      ${record.status}`);
          if (record.action) console.log(`Action:      ${record.action}`);
          if (record.reasoning) console.log(`Reasoning:   ${record.reasoning}`);
          if (record.decided_by) console.log(`Decided by:  ${record.decided_by}`);
          if (record.evidence_refs.length > 0) {
            console.log(`Evidence:    ${record.evidence_refs.join(", ")}`);
          }
          console.log(`Created:     ${record.created_at} (${formatRelativeTime(record.created_at)})`);
          if (record.updated_at) {
            console.log(`Updated:     ${record.updated_at}`);
          }
          if (record.override_reasoning) {
            console.log("");
            console.log("Override:");
            console.log(`  Reasoning: ${record.override_reasoning}`);
            if (record.override_by) console.log(`  By:        ${record.override_by}`);
            if (record.override_at) console.log(`  At:        ${record.override_at}`);
          }
          if (record.acted_at) {
            console.log("");
            console.log(`Acted at:    ${record.acted_at}`);
            if (record.result_ref) console.log(`Result ref:  ${record.result_ref}`);
          }
          console.log("");
          console.log("Item snapshot:");
          console.log(record.item_snapshot);
        });
      } catch (err) {
        error("Failed to get triage record", err);
        process.exit(EXIT_CODES.ERROR);
      }
    });
}

/**
 * Task API Routes
 *
 * REST endpoints for task operations:
 * - GET /api/tasks - list with filters and pagination
 * - GET /api/tasks/:ref - get single task
 * - POST /api/tasks/:ref/start - start task
 * - POST /api/tasks/:ref/note - add note
 *
 * AC Coverage:
 * - ac-2: GET /api/tasks returns array with status, priority, spec_ref, notes count
 * - ac-3: Status filter with multi-value support
 * - ac-4: Pagination with {items, total, offset, limit} wrapper
 * - ac-5: GET /api/tasks/:ref resolves via ReferenceIndex
 * - ac-6: POST /api/tasks/:ref/start transitions state
 * - ac-7: POST /api/tasks/:ref/note appends note
 */

import { Elysia, t } from 'elysia';
import {
  initContext,
  loadAllTasks,
  loadAllItems,
  ReferenceIndex,
  createNote,
  saveTask,
  getAuthor,
  syncSpecImplementationStatus,
  type LoadedTask,
} from '../../parser/index.js';
import { commitIfShadow } from '../../parser/shadow.js';
import type { PubSubManager } from '../websocket/pubsub';

interface TasksRouteOptions {
  pubsub: PubSubManager;
}

export function createTasksRoutes(options: TasksRouteOptions) {
  const { pubsub } = options;

  return new Elysia({ prefix: '/api/tasks' })
    // AC: @api-contract ac-2, ac-3, ac-4 - List tasks with filters and pagination
    .get(
      '/',
      async ({ query, projectContext }) => {
        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
        const ctx = await initContext(projectContext.path);
        const tasks = await loadAllTasks(ctx);
        const specItems = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, specItems);

        // Apply filters
        let filtered = tasks;

        // AC: @api-contract ac-3 - Multi-value status filter
        if (query.status) {
          const statusFilters = Array.isArray(query.status) ? query.status : [query.status];
          filtered = filtered.filter((task) => statusFilters.includes(task.status));
        }

        // Type filter (optional, not in ACs but useful)
        if (query.type) {
          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
          filtered = filtered.filter((task) => task.type && typeFilters.includes(task.type));
        }

        // Tag filter (optional, not in ACs but useful)
        if (query.tag) {
          const tagFilters = Array.isArray(query.tag) ? query.tag : [query.tag];
          filtered = filtered.filter((task) =>
            task.tags?.some((t) => tagFilters.includes(t))
          );
        }

        // AC: @api-contract ac-4 - Pagination
        const total = filtered.length;
        const offset = Number(query.offset) || 0;
        const limit = Number(query.limit) || total;

        const paginated = filtered.slice(offset, offset + limit);

        // AC: @api-contract ac-2 - Return with status, priority, spec_ref, notes count
        // AC: @web-dashboard ac-1 - Include depends_on for blocked task computation
        const items = paginated.map((task) => ({
          _ulid: task._ulid,
          slugs: task.slugs,
          title: task.title,
          status: task.status,
          priority: task.priority,
          spec_ref: task.spec_ref,
          meta_ref: task.meta_ref,
          tags: task.tags,
          depends_on: task.depends_on || [],
          notes_count: task.notes?.length || 0,
          todos_count: task.todos?.length || 0,
          started_at: task.started_at,
          completed_at: task.completed_at,
          created_at: task.created_at,
        }));

        // AC: @api-contract ac-4, @trait-api-endpoint ac-4 - Return pagination wrapper
        return {
          items,
          total,
          offset,
          limit,
        };
      },
      {
        query: t.Object({
          status: t.Optional(t.Union([t.String(), t.Array(t.String())])),
          type: t.Optional(t.Union([t.String(), t.Array(t.String())])),
          tag: t.Optional(t.Union([t.String(), t.Array(t.String())])),
          limit: t.Optional(t.String()),
          offset: t.Optional(t.String()),
        }),
      }
    )

    // AC: @api-contract ac-5 - Get single task by ref
    .get(
      '/:ref',
      async ({ params, error: errorResponse, projectContext }) => {
        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
        const ctx = await initContext(projectContext.path);
        const tasks = await loadAllTasks(ctx);
        const items = await loadAllItems(ctx);
        const index = new ReferenceIndex(tasks, items);

        // AC: @api-contract ac-5, @trait-api-endpoint ac-2 - Resolve ref via ReferenceIndex
        const result = index.resolve(params.ref);

        if (!result.ok) {
          // AC: @trait-api-endpoint ac-2 - Return 404 with error details
          return errorResponse(404, {
            error: 'not_found',
            message: `Task reference "${params.ref}" not found`,
            suggestion: 'Use kspec task list or kspec search to find valid task references',
          });
        }

        // Find the task
        const task = tasks.find((t) => t._ulid === result.ulid);
        if (!task) {
          return errorResponse(404, {
            error: 'not_found',
            message: `Reference "${params.ref}" is not a task`,
            suggestion: 'This reference might point to a spec item instead',
          });
        }

        // AC: @api-contract ac-5 - Return full task with notes, todos, dependencies
        return {
          _ulid: task._ulid,
          slugs: task.slugs,
          title: task.title,
          status: task.status,
          priority: task.priority,
          spec_ref: task.spec_ref,
          meta_ref: task.meta_ref,
          tags: task.tags,
          description: task.description,
