    expect(content).toContain("format === 'context'");
    expect(content).toContain('formatTriageContext');

    // AC: @triage-daemon-api ac-6 - JSON format
    expect(content).toContain("format: 'json'");
  });

  // AC: @triage-daemon-api ac-7
